  "delete": "ሰርዝ", "deleted": "ተሰርዟል።", "set.deleteTitle": "{name} ለዘላለም ይሰረዝ?", "set.deleteBody": "ሕንፃው፣ {u} ክፍሎቹና {f} ፎቆቹ ለዘላለም ይወገዳሉ። መመለስ አይቻልም። ይህ የሚቻለው በውስጡ ምንም ተከራይቶ ወይም ደረሰኝ ወጥቶ ስለማያውቅ ብቻ ነው።", "set.cannotDelete": "ውሎች ወይም ታሪክ አለው። በምትኩ ወደ ማህደር ያስገቡት።", "prop.deleteFloorTitle": "ፎቅ {name} ይሰረዝ?", "prop.deleteFloorBody": "ፎቁና ንድፉ ይወገዳሉ። ባዶ ፎቅ ብቻ ሊሰረዝ ይችላል።", "prop.deleteUnitTitle": "ክፍል {n} ይሰረዝ?", "prop.deleteUnitBody": "ክፍሉ ለዘላለም ይወገዳል። ምንም ውል፣ ደረሰኝ ወይም የቆጣሪ ንባብ የሌለው ክፍል ብቻ ሊሰረዝ ይችላል።", "prop.cannotDeleteUnit": "ተይዟል። መጀመሪያ ውሉን ያብቁ።", "renter.deleteTitle": "{name} ይሰረዝ?", "renter.deleteBody": "ተከራዩና ሰነዶቹ ለዘላለም ይወገዳሉ። ምንም ውል፣ ደረሰኝ ወይም ክፍያ ከሌለው ብቻ ይቻላል።", "ag.deleteTitle": "ይህ ረቂቅ ስምምነት ይሰረዝ?", "ag.deleteBody": "ረቂቁ፣ ውሎቹና የተያያዘው ቅጂ ይወገዳሉ። ፈጽሞ ያልጸደቀ ስምምነት ብቻ ሊሰረዝ ይችላል።", "err.unit_has_history": "ይህ ክፍል ውሎች፣ ንባቦች ወይም የጋራ ወጪዎች ስላሉት መሰረዝ አይቻልም።", "err.floor_has_units": "ይህ ፎቅ አሁንም ክፍሎች አሉት። መጀመሪያ ያንቀሳቅሷቸው ወይም ይሰርዟቸው።", "err.building_has_history": "ይህ ሕንፃ ውሎች፣ ንባቦች ወይም የጋራ ወጪዎች አሉት። በምትኩ ወደ ማህደር ያስገቡት።", "err.too_big_to_delete": "ይህ ሕንፃ በአንድ ጊዜ ለመሰረዝ በጣም ትልቅ ነው። በምትኩ ወደ ማህደር ያስገቡት።", "err.renter_has_history": "ይህ ተከራይ ውሎች፣ ደረሰኞች ወይም ክፍያዎች ስላሉት መሰረዝ አይቻልም።", "err.agreement_not_draft": "ፈጽሞ ያልጸደቀ ስምምነት ብቻ ሊሰረዝ ይችላል።", "err.agreement_has_bills": "ይህ ስምምነት አስቀድሞ ደረሰኞች አሉት።", "err.building_archived": "ይህ ሕንፃ በማህደር ነው። መጀመሪያ ይመልሱት።", "err.building_has_leases": "ይህ ሕንፃ ንቁ ስምምነቶች አሉት። መጀመሪያ ያብቋቸው።",
